-- Common Oracle schema fixture for oracode snapshot exports.
-- Targets 9i/10g and newer using conservative SQL and PL/SQL syntax.

SET DEFINE OFF
SET SQLBLANKLINES ON
WHENEVER SQLERROR EXIT SQL.SQLCODE

PROMPT Dropping common oracode fixture objects when present

BEGIN
  EXECUTE IMMEDIATE 'DROP MATERIALIZED VIEW OC_EMPLOYEE_MV';
EXCEPTION WHEN OTHERS THEN IF SQLCODE NOT IN (-12003, -942) THEN RAISE; END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'DROP SYNONYM OC_EMP_SYNONYM';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -1434 THEN RAISE; END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'DROP TRIGGER OC_EMP_COMPOUND_AUD_TRG';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -4080 THEN RAISE; END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'DROP TRIGGER OC_EMP_BI';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -4080 THEN RAISE; END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'DROP PACKAGE OC_REPORTING_PKG';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -4043 THEN RAISE; END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'DROP PROCEDURE OC_GIVE_RAISE';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -4043 THEN RAISE; END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'DROP FUNCTION OC_EMPLOYEE_COUNT';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -4043 THEN RAISE; END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'DROP VIEW OC_EMPLOYEE_V';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'DROP TYPE OC_NAME_T FORCE';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -4043 THEN RAISE; END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'DROP TABLE OC_23AI_BOOLEAN_FLAGS CASCADE CONSTRAINTS';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'DROP TABLE OC_21C_JSON_DOCS CASCADE CONSTRAINTS';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'DROP TABLE OC_IDENTITY_PARENT CASCADE CONSTRAINTS';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'DROP TABLE OC_11G_AUDIT_LOG CASCADE CONSTRAINTS';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'DROP TABLE OC_EMPLOYEES CASCADE CONSTRAINTS';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'DROP TABLE OC_DEPARTMENTS CASCADE CONSTRAINTS';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'DROP SEQUENCE OC_EMP_SEQ';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -2289 THEN RAISE; END IF;
END;
/

PROMPT Creating common oracode fixture objects

CREATE TABLE OC_DEPARTMENTS (
  DEPARTMENT_ID NUMBER(6) NOT NULL,
  DEPARTMENT_NAME VARCHAR2(80) NOT NULL,
  CREATED_AT DATE DEFAULT SYSDATE NOT NULL,
  CONSTRAINT OC_DEPT_PK PRIMARY KEY (DEPARTMENT_ID),
  CONSTRAINT OC_DEPT_NAME_UK UNIQUE (DEPARTMENT_NAME)
);

CREATE TABLE OC_EMPLOYEES (
  EMPLOYEE_ID NUMBER(10) NOT NULL,
  DEPARTMENT_ID NUMBER(6) NOT NULL,
  EMPLOYEE_CODE VARCHAR2(30) NOT NULL,
  FULL_NAME VARCHAR2(120) NOT NULL,
  EMAIL VARCHAR2(120),
  SALARY NUMBER(12,2) DEFAULT 0 NOT NULL,
  HIRE_DATE DATE DEFAULT SYSDATE NOT NULL,
  BIO CLOB,
  CONSTRAINT OC_EMP_PK PRIMARY KEY (EMPLOYEE_ID),
  CONSTRAINT OC_EMP_CODE_UK UNIQUE (EMPLOYEE_CODE),
  CONSTRAINT OC_EMP_SALARY_CK CHECK (SALARY >= 0),
  CONSTRAINT OC_EMP_DEPT_FK FOREIGN KEY (DEPARTMENT_ID)
    REFERENCES OC_DEPARTMENTS (DEPARTMENT_ID)
);

CREATE INDEX OC_EMP_NAME_IX ON OC_EMPLOYEES (FULL_NAME);
CREATE INDEX OC_EMP_EMAIL_IX ON OC_EMPLOYEES (EMAIL);

CREATE SEQUENCE OC_EMP_SEQ START WITH 1000 INCREMENT BY 1 NOCACHE;

INSERT INTO OC_DEPARTMENTS (DEPARTMENT_ID, DEPARTMENT_NAME) VALUES (10, 'Engineering');
INSERT INTO OC_DEPARTMENTS (DEPARTMENT_ID, DEPARTMENT_NAME) VALUES (20, 'Finance');
INSERT INTO OC_EMPLOYEES (EMPLOYEE_ID, DEPARTMENT_ID, EMPLOYEE_CODE, FULL_NAME, EMAIL, SALARY)
VALUES (1, 10, 'E001', 'Ada Lovelace', 'ada@example.invalid', 1000);
INSERT INTO OC_EMPLOYEES (EMPLOYEE_ID, DEPARTMENT_ID, EMPLOYEE_CODE, FULL_NAME, EMAIL, SALARY)
VALUES (2, 20, 'E002', 'Grace Hopper', 'grace@example.invalid', 1200);
COMMIT;

COMMENT ON TABLE OC_DEPARTMENTS IS 'oracode common fixture departments';
COMMENT ON COLUMN OC_DEPARTMENTS.DEPARTMENT_NAME IS 'Stable department display name';
COMMENT ON TABLE OC_EMPLOYEES IS 'oracode common fixture employees';
COMMENT ON COLUMN OC_EMPLOYEES.BIO IS 'CLOB column for DBMS_METADATA coverage';

CREATE OR REPLACE VIEW OC_EMPLOYEE_V AS
SELECT E.EMPLOYEE_ID,
       E.EMPLOYEE_CODE,
       E.FULL_NAME,
       D.DEPARTMENT_NAME,
       E.SALARY
  FROM OC_EMPLOYEES E,
       OC_DEPARTMENTS D
 WHERE D.DEPARTMENT_ID = E.DEPARTMENT_ID;

CREATE OR REPLACE TYPE OC_NAME_T AS OBJECT (
  FIRST_NAME VARCHAR2(60),
  LAST_NAME VARCHAR2(60),
  MEMBER FUNCTION DISPLAY_NAME RETURN VARCHAR2
);
/
SHOW ERRORS TYPE OC_NAME_T

CREATE OR REPLACE TYPE BODY OC_NAME_T AS
  MEMBER FUNCTION DISPLAY_NAME RETURN VARCHAR2 IS
  BEGIN
    RETURN FIRST_NAME || ' ' || LAST_NAME;
  END;
END;
/
SHOW ERRORS TYPE BODY OC_NAME_T

CREATE OR REPLACE FUNCTION OC_EMPLOYEE_COUNT RETURN NUMBER IS
  L_COUNT NUMBER;
BEGIN
  SELECT COUNT(*) INTO L_COUNT FROM OC_EMPLOYEES;
  RETURN L_COUNT;
END;
/
SHOW ERRORS FUNCTION OC_EMPLOYEE_COUNT

CREATE OR REPLACE PROCEDURE OC_GIVE_RAISE(
  P_EMPLOYEE_ID IN NUMBER,
  P_AMOUNT IN NUMBER
) IS
BEGIN
  UPDATE OC_EMPLOYEES
     SET SALARY = SALARY + P_AMOUNT
   WHERE EMPLOYEE_ID = P_EMPLOYEE_ID;
END;
/
SHOW ERRORS PROCEDURE OC_GIVE_RAISE

CREATE OR REPLACE PACKAGE OC_REPORTING_PKG AS
  FUNCTION EMPLOYEE_LABEL(P_EMPLOYEE_ID IN NUMBER) RETURN VARCHAR2;
END OC_REPORTING_PKG;
/
SHOW ERRORS PACKAGE OC_REPORTING_PKG

CREATE OR REPLACE PACKAGE BODY OC_REPORTING_PKG AS
  FUNCTION EMPLOYEE_LABEL(P_EMPLOYEE_ID IN NUMBER) RETURN VARCHAR2 IS
    L_LABEL VARCHAR2(200);
  BEGIN
    -- Lower-case keywords in comments should remain untouched by the sanitizer.
    SELECT EMPLOYEE_CODE || ': ' || FULL_NAME
      INTO L_LABEL
      FROM OC_EMPLOYEES
     WHERE EMPLOYEE_ID = P_EMPLOYEE_ID;
    RETURN L_LABEL;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN 'select from fixture fallback';
  END EMPLOYEE_LABEL;
END OC_REPORTING_PKG;
/
SHOW ERRORS PACKAGE BODY OC_REPORTING_PKG

CREATE OR REPLACE TRIGGER OC_EMP_BI
BEFORE INSERT ON OC_EMPLOYEES
FOR EACH ROW
BEGIN
  IF :NEW.EMPLOYEE_ID IS NULL THEN
    SELECT OC_EMP_SEQ.NEXTVAL INTO :NEW.EMPLOYEE_ID FROM DUAL;
  END IF;
END;
/
SHOW ERRORS TRIGGER OC_EMP_BI

PROMPT Common oracode fixture loaded
